import{TORNADO_CONFIG as u}from"./config.min.js";import{spineAt as v}from"./funnel.min.js";export function windAt(h,p,n,f=u){const t=f.wind,r=v(0,n),c=r.x-h,e=r.z-p,s=Math.max(Math.hypot(c,e),1),m=c/s,d=e/s,w=t.inflow*n.inflow,l=Math.max(n.dust,n.extent*.6),o=t.vortex*l/(1+(s/t.vortexRadius)**2),z=-d,M=m;let x=t.ambient.x+m*(w+o*t.inward)+z*o*t.swirl,a=t.ambient.z+d*(w+o*t.inward)+M*o*t.swirl;const i=Math.hypot(x,a);return i>t.max&&(x*=t.max/i,a*=t.max/i),{x,z:a,speed:Math.min(i,t.max)}}
